mapper.select:
SELECT * FROM stu_student
WHERE deleted = 0

    AND student_no LIKE CONCAT('%', #{query.studentNo}, '%')


    AND name LIKE CONCAT('%', #{query.name}, '%')


    AND department = #{query.department}


    AND major = #{query.major}


    AND class_no = #{query.classNo}


    AND academic_status = #{query.academicStatus}


    AND counselor_id = #{query.counselorId}


    AND YEAR(enrollment_date) = #{query.enrollmentYear}

ORDER BY created_at DESC
